import{_ as n,l as o,o as a,c as l,v as r,p as d,x as i,d as D,i as c,S as A}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"KV RDMA 远端拉取","description":"","frontmatter":{"title":"KV RDMA 远端拉取","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kv-rdma-fetch.md","filePath":"llm/kv-rdma-fetch.md","lastUpdated":1789023840000}'),s={name:"llm/kv-rdma-fetch.md"};function h(p,e,M,P,R,m){const t=o("Mermaid");return a(),l("div",null,[e[1]||(e[1]=r('<h1 id="kv-rdma-远端拉取" tabindex="-1">KV RDMA 远端拉取 <a class="header-anchor" href="#kv-rdma-远端拉取" aria-label="Permalink to &quot;KV RDMA 远端拉取&quot;">​</a></h1><div class="epigraph"><p>预填充和解码拆到不同机器之后，键值必须在网上搬家；走 GPUDirect RDMA，网卡对着 HBM 做远程写，而不是先弹到主机内存再拷回卡上。</p><footer>—— Qin 等，Mooncake Transfer Engine；对照 Zhong 等 DistServe 把 KV 作为分离式服务的中间状态</footer></div><p>分层缓存解决「这份 KV 放哪一层介质」。集群一放大，问题变成「这份 KV 在哪台机器上，解码卡怎么把它读过来」。Prefill 实例写出分页块，Decode 实例要在注意力开始前看到同一份字节。TCP 加主机缓冲能跑通，但体积随层数、KV 头、精度和长度线性涨，弹跳路径会把 TTFT 的下界钉在主机内存拷贝上。RDMA 远端拉取把块登记成可远程访问的内存，对端用单向写或读直接落到 GPU 或 pin 住的主机池。本篇写这条数据路径；介质层次见 <a href="/llm/kv-tiered-storage">分层 KV</a>，网卡直达显存的背景见 <a href="/llm/infiniband-gpudirect">InfiniBand 与 GPUDirect</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DistServe（Zhong、Liu、Chen、Hu、Zhu、Liu、Jin、Zhang 等，OSDI 2024，arXiv:2401.09670）把预填充与解码拆到不同 GPU，消除两阶段互相抢连续批，并使两套并行度可以分别选。代价是中间状态——主要是 KV——必须跨设备移动。Splitwise（Patel 等，ISCA 2024）在生产轨迹上做了同类拆分。Mooncake（Qin 等，arXiv:2407.00079）进一步把 KV 当成一等资源：预填充集群、解码集群、以及由各节点 CPU/DRAM/SSD/RDMA 拼成的解聚缓存池。调度器问的不是「哪张卡最闲」，而是「KV 在哪、搬过去要多久、会不会打穿 SLO」。</p><p>传输体积很容易估。每层每 token 的 KV 大约是 \\(2 h_{\\mathrm{kv}} d_k\\) 个数（MLA 则是潜向量加小 RoPE 键）。乘上层数、精度字节、提示长度，一次长上下文交接可以到数百 MB 乃至数 GB。PCIe 弹跳路径上，主机拷贝与网卡 DMA 串起来；GPUDirect RDMA 让 NIC 成为 GPU 的 PCIe 对等体，注册过的 HBM 缓冲区可以直接当 RDMA 本地或远端内存。Mooncake 的 Transfer Engine 把 RDMA、TCP、NVLink 等后端收成统一搬运层，SGLang 与 vLLM 都把它接成 PD 分离和跨实例共享的连接器。</p><h3 id="延迟预算里传输必须可重叠" tabindex="-1">延迟预算里传输必须可重叠 <a class="header-anchor" href="#延迟预算里传输必须可重叠" aria-label="Permalink to &quot;延迟预算里传输必须可重叠&quot;">​</a></h3><p>预填充还在算后面的层时，已经算完的层可以往解码侧推——层间流水把传输藏进剩余计算。若等到整网前向结束再一次性 dump，解码实例会空等一个完整 TTFT。反过来，解码侧若在块到齐之前就开注意力，会读到半新半旧的块表。协议必须有「层 \\(k\\) 的块已提交」的完成语义，而不是只靠一条连接上的字节流。</p><p><span class="marginnote">拓扑比协议更先决定天花板。NIC 与 GPU 同属一条 PCIe 交换机（PIX）时，GPUDirect 才能接近线路速率；跨根复合物或跨 NUMA 时，BAR1 窗口变窄，pin 住的主机内存池反而更快。vLLM/Mooncake 文档把 CPU pinned pool 写成多数拓扑的默认，不是因为 RDMA 理论不行，而是因为机架布线经常不是 PIX。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="注册、块粒度、零拷贝" tabindex="-1">注册、块粒度、零拷贝 <a class="header-anchor" href="#注册、块粒度、零拷贝" aria-label="Permalink to &quot;注册、块粒度、零拷贝&quot;">​</a></h3><p>RDMA 要求内存先注册（<code>ibv_reg_mr</code> 或 DMA-BUF）。服务引擎不能对每个 token 注册一次：开销和 pin 住的页表都吃不消。实践是预注册一块大池，KV 按 <a href="/llm/paged-kv-block-size">分页块</a> 从池里切。Mooncake 侧可以是 CPU pinned 池（GPU→池→RDMA→对端池→GPU）或 CUDA 池（GPUDirect，NIC 读 BAR1）。块哈希（前缀缓存用的指纹）同时当对象键：对端按哈希 RDMA Read，或本端 RDMA Write 到对端已公布的地址。</p><p>完成队列与批量是延迟的另一半。一块一块轮询会把小块的 QP 往返变成主导；按层或按若干块打包，一次发一串 RDMA Write，用一条完成事件表示「这一层可解码」。PCIe relaxed ordering（Mooncake 里 <code>IBV_ACCESS_RELAXED_ORDERING</code> / <code>MC_IB_PCI_RELAXED_ORDERING</code>）在 GPU 路径上往往决定能不能从十几 GB/s 走到接近 400 Gb/s 网卡的有效带宽——这是工程开关，不是算法创新，但关掉它，论文里的「RDMA 很快」会在基准上消失。</p><h3 id="拉取还是推送" tabindex="-1">拉取还是推送 <a class="header-anchor" href="#拉取还是推送" aria-label="Permalink to &quot;拉取还是推送&quot;">​</a></h3><p>两种方向。推送：预填充实例在层结束时把块写到解码实例公布的缓冲。拉取：解码实例（或缓存池客户端）拿着块地址去读。推送适合「一对一交接、解码槽位已预留」；拉取适合「全局池、多个解码副本按需取热前缀」。Mooncake Store 把后者做成集群级前缀缓存：实例按哈希复用，而不是每条请求都从预填充卡再传一遍。失败要有超时与回退：RDMA 读失败应落到重做预填充，而不是让解码读零页。</p>',15)),(a(),d(A,null,{default:i(()=>[c(t,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20LR%0A%20%20P%5B%22Prefill%20GPU%20%E5%86%99%E5%87%BA%20KV%20%E5%9D%97%22%5D%20--%3E%20REG%5B%22%E6%B3%A8%E5%86%8C%E6%B1%A0%20%2F%20%E5%85%AC%E5%B8%83%E5%9C%B0%E5%9D%80%22%5D%0A%20%20REG%20--%3E%20RDMA%5B%22RDMA%20Write%20%E6%88%96%20Read%22%5D%0A%20%20POOL%5B%22%E8%A7%A3%E8%81%9A%20DRAM%2FSSD%20%E6%B1%A0%22%5D%20--%3E%20RDMA%0A%20%20RDMA%20--%3E%20D%5B%22Decode%20GPU%20%E5%9D%97%E8%A1%A8%22%5D%0A%20%20D%20--%3E%20ATT%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%E6%A0%B8%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[D(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="为什么-rdma-对-kv-特别合适" tabindex="-1">为什么 RDMA 对 KV 特别合适 <a class="header-anchor" href="#为什么-rdma-对-kv-特别合适" aria-label="Permalink to &quot;为什么 RDMA 对 KV 特别合适&quot;">​</a></h3><p>KV 块在写出后只读，没有训练梯度那种双向归约。单向 RDMA Write 语义与「把只读块放到对端」同构，不需要 NCCL All-Reduce 的树。消息大小从几十 KB（单层一块）到数 MB（一层整序列），正好落在 InfiniBand 有吞吐的区间；过小则 QP 速率不够，过大则占满 HBM 注册池。GPUDirect 省掉的是主机弹跳，不是集合通信算法。</p><p>与专家并行的 All-to-All 不同：EP 每步都要按路由打散 token，KV 拉取通常一次交接、随后本地解码。因此可以把昂贵的注册与连接建立摊到会话生命周期，而不是摊到每个 token。会话亲和（<a href="/llm/kv-aware-routing">KV 感知路由</a>）进一步减少「每轮重新拉取同一前缀」。</p><p><span class="marginnote">IBGDA（InfiniBand GPUDirect Async）让 GPU 自己提交工作到网卡，少一次 CPU 敲门。DeepSeek-V3 报告在解码期 EP 的点对点 IB 传输上使用它以降延迟。KV 拉取同样受益，但实现要处理 GPU 侧门铃与完成通知，不能假设 Verbs 主机路径直接可搬。</span></p><h3 id="与分层缓存的交界" tabindex="-1">与分层缓存的交界 <a class="header-anchor" href="#与分层缓存的交界" aria-label="Permalink to &quot;与分层缓存的交界&quot;">​</a></h3><p>远端拉取的源不必是预填充卡的 HBM。它可以是本机 DRAM、远端 DRAM、甚至 SSD 上的对象经网关注册后暴露。调度器要同时看「计算空闲」和「字节在哪」。Mooncake 的 Conductor 一类索引器维护前缀命中与介质（gpu/cpu/disk），路由器按最长匹配选实例，传输引擎再决定是本机映射还是 RDMA。没有索引、只靠随机挑解码卡，RDMA 再快也在搬不该搬的块。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>RDMA 不是免费带宽。QP 数量、CQ 轮询线程、注册池大小、ECMP 源端口、NUMA 亲和都会把有效带宽打到标称的几分之一。安全上，把 HBM 暴露给 RDMA 等于扩大信任域：生产应隔离租户、限制 rkey 范围，而不是整卡开放。TCP 回退必须存在，否则机房改一次网卡驱动服务就停。</p><p>不要把 DistServe 的 goodput 数字当成「接了 RDMA 就 7.4×」：那是分离计算干扰、重配并行度之后的端到端结果，传输只是其中一项成本。不要在非 PIX 拓扑上强开 GPUDirect 再抱怨「RDMA 很慢」。MLA/GQA 缩小了 \\(M\\)，同一条链路能叠更长上下文，这是模型侧给传输的礼物，不是传输协议自己变快。</p><p><span class="marginnote">出处：Qin 等，<em>Mooncake: A KVCache-centric Disaggregated Architecture for LLM Serving</em>，arXiv:2407.00079；Zhong 等，<em>DistServe</em>，OSDI 2024，arXiv:2401.09670；NVIDIA GPUDirect RDMA 文档；DeepSeek-V3 报告中的 IBGDA 解码通信。实现以 Mooncake Transfer Engine 与各引擎 connector 为准。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PD 分离与全局前缀缓存都要把 KV 块跨机移动；RDMA 远端拉取是这条路径的低延迟实现。</li><li>GPUDirect 去掉主机弹跳，但依赖 NIC–GPU 的 PCIe 近邻；否则 pinned CPU 池更稳。</li><li>块粒度注册、层间流水、完成语义，比「用了 RDMA」四个字更决定 TTFT。</li><li>只读块适合单向 Write/Read；会话亲和减少重复拉取。</li><li>失败回退是重做预填充，不是读未完成的块表。</li><li>出处：Mooncake；DistServe；GPUDirect RDMA。</li></ul>',13))])}const E=n(s,[["render",h]]);export{u as __pageData,E as default};
